# TASK: restaurar universo movers en ganesha_ejecutor (merge backup + reconciliacion)
import base64,hashlib,json,os,py_compile,re,subprocess,time,urllib.request
B="/home/opc/bot_semillas"
SRC_B64=""
def scrub(s):
    if not s: return s
    s=re.sub(r"(github_pat_[A-Za-z0-9_]+|gh[posru]_[A-Za-z0-9]+|sk-ant-[A-Za-z0-9_\\-]+)","<TOK>",s)
    return re.sub(r"[A-Za-z0-9]{56,}","<REDACTED>",s)
tok=""
try:
    for L in open(B+"/.env"):
        m=re.search(r"(github_pat_[A-Za-z0-9_]+|gh[posru]_[A-Za-z0-9]+)",L)
        if m: tok=m.group(1)
except Exception: pass
info={"task":"restore_universo_movers","now":time.strftime("%Y-%m-%d %H:%M:%SZ",time.gmtime()),"pasos":[]}
def step(s): info["pasos"].append(s); print("[univ]",s)
try:
    src=base64.b64decode(SRC_B64)
    info["sha256"]=hashlib.sha256(src).hexdigest()[:16]
    tmp=B+"/_new_ganesha_ejecutor.py"
    open(tmp,"wb").write(src)
    py_compile.compile(tmp,doraise=True)
    step("compile OK (%d bytes)"%len(src))
    tgt=B+"/ganesha_ejecutor.py"
    bak=B+"/ganesha_ejecutor.py.bak.pre_univ"
    if os.path.exists(tgt) and not os.path.exists(bak):
        open(bak,"wb").write(open(tgt,"rb").read()); step("backup -> .bak.pre_univ")
    os.replace(tmp,tgt); step("instalado")
    info["movers_flag"]=os.path.exists(B+"/ejecutor/MOVERS")
    test=("import sys; sys.path.insert(0,%r); import ganesha_ejecutor as G;"
          "assert hasattr(G,'reconcile_manual'), 'falta reconcile';"
          "assert hasattr(G,'mover_symbols'), 'falta movers';"
          "assert 'breakeven_r' not in G.P;"
          "print('ok reconcile+movers')")%B
    r=subprocess.run([B+"/venv/bin/python","-c",test],capture_output=True,text=True,timeout=120,cwd=B)
    info["test_stdout"]=scrub(r.stdout[-500:]); info["test_stderr"]=scrub(r.stderr[-500:])
    step("test rc=%d"%r.returncode)
    info["ok"]=(r.returncode==0)
except Exception as e:
    info["ok"]=False; info["error"]=scrub(str(e)[:300])
U="https://api.github.com/repos/calcagnoagustin/radar/contents/docs/_diag.json"
def R(m,d=None):
    q=urllib.request.Request(U,data=d,method=m); q.add_header("Authorization","token "+tok); q.add_header("User-Agent","univ")
    return urllib.request.urlopen(q,timeout=30).read()
sha=None
try: sha=json.loads(R("GET")).get("sha")
except Exception: pass
p={"message":"restore universo movers","content":base64.b64encode(json.dumps(info,indent=1).encode()).decode()}
if sha: p["sha"]=sha
try: R("PUT",json.dumps(p).encode()); print("REPORTADO ok=%s"%info.get("ok"))
except Exception as e: print("PUSH_ERR",e)
